link 3.4s linear infinite;transform-box:fill-box;transform-origin:50% 50%}.b2wg{animation:flap .6s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 0%}.b2bd{animation:bob .8s ease-in-out infinite}.b2ey{animation:blink 3.4s linear infinite;transform-box:fill-box;transform-origin:50% 50%}.nt0{animation:rise 3.2s ease-out infinite;animation-delay:0.0s}.nt1{animation:rise 3.2s ease-out infinite;animation-delay:1.1s}.nt2{animation:rise 3.2s ease-out infinite;animation-delay:2.2s}.lb1{animation:pop .5s ease-out both;animation-delay:0.2s}.lb2{animation:pop .5s ease-out both;animation-delay:0.8s}.sb{font-family:Arial,sans-serif;font-weight:700}.st{font-family:Arial,sans-serif}@media (prefers-reduced-motion:reduce){.scn *{animation:none !important}animate{display:none}}</style><g class=\"scn\"><rect x=\"0\" y=\"0\" width=\"720\" height=\"300\" rx=\"20\" fill=\"#eaf5ff\"/><path d=\"M110 190 Q 360 176 640 186\" fill=\"none\" stroke=\"#8b5a2b\" stroke-width=\"12\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><g class=\"br\"><path d=\"M470 182 q 20 -26 44 -30\" fill=\"none\" stroke=\"#8b5a2b\" stroke-width=\"7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"500\" cy=\"150\" r=\"5\" fill=\"#4cbb59\"/><circle cx=\"512\" cy=\"160\" r=\"4\" fill=\"#3fa64b\"/></g><g class=\"b1bd\"><line x1=\"287.4\" y1=\"186\" x2=\"287.4\" y2=\"195.2\" stroke=\"#3b82d6\" stroke-width=\"2.9\" stroke-linecap=\"round\"/><line x1=\"296.6\" y1=\"186\" x2=\"296.6\" y2=\"195.2\" stroke=\"#3b82d6\" stroke-width=\"2.9\" stroke-linecap=\"round\"/><ellipse cx=\"292\" cy=\"179.1\" rx=\"17.2\" ry=\"12.6\" fill=\"#5aa9f0\"/><circle cx=\"306.9\" cy=\"167.6\" r=\"10.3\" fill=\"#5aa9f0\"/><path d=\"M316.1 167.6 l10.3 3.4 l-10.3 3.4 z\" fill=\"#f59e0b\"/><g class=\"b1ey\"><circle cx=\"309.2\" cy=\"165.3\" r=\"2\" fill=\"#1f2937\"/></g><g class=\"b1wg\"><path d=\"M289.7 176.8 q8.0 -3.4 11.5 4.6 q-9.2 4.6 -11.5 -4.6 z\" fill=\"#3b82d6\"/></g></g><g class=\"b2bd\"><line x1=\"427.