dth=\"210\" height=\"132\" rx=\"14\" fill=\"#ffffff\" stroke=\"#f59e0b\" stroke-width=\"3\"/><circle cx=\"145\" cy=\"266\" r=\"13\" fill=\"#ea580c\"/><text x=\"145\" y=\"318\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#7c2d12\" class=\"sb\">Statement</text><text x=\"145\" y=\"344\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#334155\" class=\"st\">The dog barked.</text><rect x=\"255\" y=\"228\" width=\"210\" height=\"132\" rx=\"14\" fill=\"#ffffff\" stroke=\"#3b82f6\" stroke-width=\"3\"/><text x=\"360\" y=\"290\" text-anchor=\"middle\" font-size=\"46\" font-weight=\"700\" fill=\"#2563eb\" class=\"sb\">?</text><text x=\"360\" y=\"318\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#1e3a8a\" class=\"sb\">Question</text><text x=\"360\" y=\"344\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#334155\" class=\"st\">Did you see the dog?</text><rect x=\"470\" y=\"228\" width=\"210\" height=\"132\" rx=\"14\" fill=\"#ffffff\" stroke=\"#a855f7\" stroke-width=\"3\"/><text x=\"575\" y=\"290\" text-anchor=\"middle\" font-size=\"46\" font-weight=\"700\" fill=\"#7c3aed\" class=\"sb\">!</text><text x=\"575\" y=\"318\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#5b21b6\" class=\"sb\">Strong feeling</text><text x=\"575\" y=\"344\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#334155\" class=\"st\">Watch out for that dog!</text><text x=\"430\" y=\"214\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#7c2d12\" class=\"st\">Watch the capital letter grow and the full stop drop.</text></g></svg>",
