form-origin:50% 0%}.wkaR{animation:armB 0.7s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 0%}.wkhd{animation:bob 0.7s ease-in-out infinite}.wkey{animation:blink 4.2s linear infinite;transform-box:fill-box;transform-origin:50% 50%}.wkbd{animation:bob 0.7s ease-in-out infinite}.wklL{animation:legA 0.7s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 0%}.wklR{animation:legB 0.7s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 0%}.fx{animation:pop .6s ease-out both;animation-delay:3.4s}.sb{font-family:Arial,sans-serif;font-weight:700}@media (prefers-reduced-motion:reduce){.scn *{animation:none !important}animate{display:none}}</style><g class=\"scn\"><rect x=\"0\" y=\"0\" width=\"720\" height=\"352\" rx=\"20\" fill=\"#eef2ff\"/><path d=\"M140 170 H580\" fill=\"none\" stroke=\"#c7d2fe\" stroke-width=\"10\" stroke-linecap=\"round\" stroke-dasharray=\"12 10\"><animate attributeName=\"stroke-dashoffset\" values=\"0;-44\" keyTimes=\"0;1\" dur=\"1.4s\" repeatCount=\"indefinite\"/></path><g class=\"sg0\"><circle cx=\"140\" cy=\"156\" r=\"44\" fill=\"#dbeafe\" stroke=\"#1e40af\" stroke-width=\"3\"/><text x=\"140\" y=\"166\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"700\" fill=\"#1e40af\" class=\"sb\">Aa.</text></g><text x=\"140\" y=\"226\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#1e40af\" class=\"sb\">Capital + end mark</text><g class=\"sg1\"><circle cx=\"360\" cy=\"156\" r=\"44\" fill=\"#ffedd5\" stroke=\"#9a3412\" stroke-width=\"3\"/><text x=\"360\" y=\"166\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"700\" fill=\"#9a3412\" class=\"sb\">?</text></g><text x=\"360\" y=\"226\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#9a3412\" class=\"sb\">Who or what? Did what?</text><g class=\"sg2\"><circle cx=\"580\" cy=\"156\" r=\"44\" fill=\"#dcfce7\" stroke=\"#166534\" stroke-width=\"3\"/><text x=\"580\" y=\"166\" text-anchor=\"middle\" font-size=\"30\" font-wei